import { Image } from "./image";
import React from "react";
import Slider from "react-slick";  // Import the Slider component

export const Poster = (props) => {
  // Slick settings for the slideshow
  const settings = {
    dots: true,            // Show navigation dots
    infinite: true,        // Infinite loop
    speed: 500,            // Transition speed (ms)
    slidesToShow: 1,       // Show 1 slide at a time
    slidesToScroll: 1,     // Scroll 1 slide at a time
    autoplay: true,        // Enable autoplay
    autoplaySpeed: 3000,   // Speed of autoplay (ms)
    arrows: true,          // Show previous and next arrows
  };
  return (
    <div id="poster" className="text-center">
      <div className="">
        <div className="section-title padding-title">
          <h2></h2>
          <p>
          </p>
        </div>
        <div className="row">
        {props.data && props.data.length === 2 ? (
        <div className="row">
          {/* Small image */}
          <div className="small-image col-md-4 col-lg-push-1">
            <Image
              title={props.data[1].title}
              largeImage={props.data[1].largeImage}
              smallImage={props.data[1].smallImage}
            />
          </div>

          {/* Big image slideshow */}
          <div className="big-image col-md-6 col-lg-push-1">
            <Slider {...settings}>
              {props.data.map((d, i) => (
                <div key={i}>
                  <Image
                    title={d.title}
                    largeImage={d.largeImage}
                    smallImage={d.smallImage}
                  />
                </div>
              ))}
            </Slider>
          </div>
        </div>
      ) : (
        "Loading..."
      )}
        </div>
      </div>
    </div>
  );
};
